input.sparql:
SELECT ?point ?time ?uri WHERE {
  ?ch a/ref:type brick:Chiller ; rdfs:label "Chiller01" .
  ?point a ?pc ; brick:isPartOf ?ch ; ref:hasExternalReference ?uri .
  OPTIONAL { ?point ref:hasTimeseriesId ?time }
  ?pc rdfs:subClassOf* ?q .
}

SELECT ?ch ?label WHERE {
  ?ch a ?t .
  ?t rdfs:subClassOf* brick:Chiller .
  ?ch rdfs:label ?label .
  FILTER regex(?label, "Chiller01", "i")
}

SELECT ?p ?pc WHERE {
  ?p brick:isPartOf ?ch .
  ?p a ?pc .
  FILTER regex(str(?ch), "Chiller01")
}

SELECT ?ch ?label WHERE {
  ?ch a brick:Chiller .
  ?ch rdfs:label ?label .
} LIMIT 50

SELECT ?p ?label WHERE {
  ?p a ?t .
  ?t rdfs:subClassOf* brick:Power .
  ?p rdfs:label ?label .
} LIMIT 10

